1	// Ảnh và số đo trước / sau cho việc nâng cấp sông Hàn + nhà hai bờ (docs/ai/PROJECT_STATE.md, spec 2026-11-13-ven-song-chan-thuc-design.md).
2	// GPU THẬT (không SwiftShader): cùng góc camera, cùng điều kiện (ngày, hoàng hôn, đêm, mưa, bão) để so trước / sau. Không chấm đạt / lỗi theo ms.
3	// Ghi tests/screens/ven-song/<nhãn>/<góc>-<điều kiện>.png và metrics.json (lệnh vẽ, tam giác, ms GPU mỗi khung, thời gian mở trang, số program).
4	//
5	//   npm run build && node tests/ven-song-shots.mjs --label=truoc [--w=1600] [--h=900] [--only=ngay,dem] [--cams=nha-mau,tx-tay] [--query=ground=off] [--noshots] [--soft]
6	import { fileURLToPath } from 'node:url';
7	import fs from 'node:fs/promises';
8	import path from 'node:path';
9	import { chromium } from 'playwright';
10	import { serveDir, openApp, frames, launch } from './lib.mjs';
11	import { setWx } from './weather-lib.mjs';
12	
13	const arg = (k, d) => process.argv.find((a) => a.startsWith(`--${k}=`))?.slice(k.length + 3) ?? d;
14	const label = arg('label', 'last'), W = +arg('w', 1600), H = +arg('h', 900), only = arg('only', '').split(',').filter(Boolean), cams = arg('cams', '').split(',').filter(Boolean), noShots = process.argv.includes('--noshots');
15	
16	/* Góc camera cố định (m, hệ trục của cảnh). Không đổi giữa các lần chạy: ảnh trước / sau phải chồng khít. */
17	const CAMS = {
18	  'tren-cao': { pos: [-430, 330, 560], target: [0, 12, 0] },              // toàn cảnh Cầu Rồng (góc mặc định)
19	  'doc-song': { pos: [0, 45, -640], target: [0, 80, -1150] },             // giữa sông nhìn về Bắc, hai bờ hai bên
20	  'sat-nuoc': { pos: [-120, 5, -260], target: [60, 2, -700] },            // sát mặt nước, nhìn chéo sang bờ Đông và Cầu sông Hàn
21	  'bo-ke': { pos: [-266, 4.6, -1165], target: [-40, 9, -1075] },          // đứng trên kè Bạch Đằng nhìn Cầu sông Hàn
22	  'du-luon': { pos: [40, 140, 520], target: [-60, 0, -500] },             // tầm bay dù lượn dọc sông
23	  'mat-pho': { pos: [-299, 1.8, 120], target: [-200, 8, 0] },             // ngang tầm xe trên Bạch Đằng
24	  'nha-tay': { pos: [120, 60, -420], target: [-420, 30, -560] },          // từ giữa sông nhìn thẳng dãy nhà bờ Tây
25	  'nha-dong': { pos: [-120, 60, 420], target: [420, 30, 560] },           // từ giữa sông nhìn thẳng dãy nhà bờ Đông
26	  'nha-mau': { pos: [-200, 40, 20], target: [-400, 25, -150] },
27	  'tx-tay': { pos: [-520, 620, -299], target: [-520, 0, -300] },         // từ trên xuống dải nhà bờ Tây phía Bắc Cầu Rồng (bãi trống, chuyển tiếp sang phố trong)
28	  'tx-dong': { pos: [560, 620, 301], target: [560, 0, 300] },            // từ trên xuống dải nhà bờ Đông phía Nam Cầu Rồng
29	  'pho-trong': { pos: [-300, 90, -250], target: [-1100, 30, -420] },   // từ mép sông nhìn sâu vào phố trong bờ Tây: chỗ dải ven sông gặp rừng tháp
30	  'ke-tay': { pos: [-236, 5, -292], target: [-263, 1.2, -258] },         // sát kè bờ Tây: mũ kè, chân kè hai bậc, trụ kè, bậc thềm tại z = −260 (M3 Task 3.4)
31	  'ke-dong': { pos: [225, 14, 100], target: [263, 1, 135] }               // nhìn chéo xuống kè bờ Đông phía Nam Cầu Rồng, bậc thềm tại z = 130
32	
33	};
34	/* Điều kiện: night 0..1 của dayNight, preset thời tiết */
35	const CONDS = {
36	  ngay: { night: 0, wx: 'now' }, 'hoang-hon': { night: 0.62, wx: 'now' }, dem: { night: 1, wx: 'now' },
37	  mua: { night: 0, wx: 'rain' }, bao: { night: 0, wx: 'storm' }, 'mua-dem': { night: 1, wx: 'rain' }
38	};
39	const GPU_AT = [['tren-cao', 'ngay'], ['tren-cao', 'dem'], ['sat-nuoc', 'ngay'], ['doc-song', 'dem'], ['du-luon', 'mua']];
40	
41	const out = fileURLToPath(new URL(`./screens/ven-song/${label}/`, import.meta.url));
42	await fs.mkdir(out, { recursive: true });
43	const srv = await serveDir(arg('dist', '') ? path.resolve(arg('dist', '')) : fileURLToPath(new URL('../dist/', import.meta.url)));   // --dist=<thư mục>: đo một bản build khác (vd. worktree của main) để so A/B
44	const args = ['--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'];
45	if (process.platform === 'win32') args.unshift('--use-angle=d3d11');
46	const browser = process.argv.includes('--soft') ? await launch() : await chromium.launch({ headless: true, args, executablePath: process.env.CHROMIUM_PATH || undefined });   // --soft: máy không có GPU (SwiftShader như các test khác): chỉ lấy ảnh + lệnh vẽ, không đo ms
47	const t0 = Date.now();
48	const { page, errors } = await openApp(browser, srv.url + '?perf' + (arg('query', '') ? '&' + arg('query', '') : ''), { width: W, height: H });
49	const openMs = Date.now() - t0;
50	const info = await page.evaluate(() => {
51	  const A = window.__app, gl = A.renderer.getContext(), d = gl.getExtension('WEBGL_debug_renderer_info');
52	  return { gpu: d ? gl.getParameter(d.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER), timer: !!gl.getExtension('EXT_disjoint_timer_query_webgl2'),
53	    firstFrameMs: Math.round(A.perf.firstFrameMs), programs: A.renderer.info.programs.length, textures: A.renderer.info.memory.textures, geometries: A.renderer.info.memory.geometries };
54	});
55	console.log(`GPU: ${info.gpu} · ${W}x${H} · mở trang ${(openMs / 1000).toFixed(1)} s · khung đầu ${info.firstFrameMs} ms · ${info.programs} program`);
56	const soft = /swiftshader|llvmpipe|software/i.test(info.gpu);
57	
58	const setCam = (c) => page.evaluate((c) => {
59	  const A = window.__app; A.cam.mode = 'orbit'; A.controls.enabled = true; A.controls.maxPolarAngle = Math.PI * 0.97;
60	  A.camera.position.set(...c.pos); A.controls.target.set(...c.target); A.controls.update();
61	}, c);
62	const setNight = (n) => page.evaluate((n) => { const d = window.__app.dayNight; d.target = d.night = n; }, n);
63	const stats = () => page.evaluate(() => { const R = window.__app.renderer; R.info.reset(); R.render(window.__app.scene, window.__app.camera); return { calls: R.info.render.calls, tris: R.info.render.triangles }; });
64	const gpuMs = () => page.evaluate(async () => {
65	  const A = window.__app, R = A.renderer, gl = R.getContext(), ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
66	  const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms)), draw = () => R.render(A.scene, A.camera);
67	  const one = async () => {
68	    draw(); draw();
69	    const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
70	    for (let i = 0; i < 12; i++) draw();
71	    gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
72	    for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; }
73	    const bad = gl.getParameter(ext.GPU_DISJOINT_EXT), ns = gl.getQueryParameter(q, gl.QUERY_RESULT); gl.deleteQuery(q);
74	    return bad ? -1 : ns / 1e6 / 12;
75	  };
76	  const a = []; for (let i = 0; i < 7; i++) a.push(await one());
77	  const ok = a.filter((x) => x > 0).sort((x, y) => x - y);
78	  return ok.length ? { med: ok[ok.length >> 1], min: ok[0], max: ok[ok.length - 1] } : null;
79	});
80	
81	const metrics = { label, when: new Date().toISOString(), gpu: info.gpu, size: [W, H], openMs, firstFrameMs: info.firstFrameMs, programs: info.programs, textures: info.textures, geometries: info.geometries, views: {}, gpuMs: {} };
82	for (const [cn, cond] of Object.entries(CONDS)) {
83	  if (only.length && !only.includes(cn)) continue;
84	  await setNight(cond.night); await setWx(page, cond.wx);
85	  for (const [vn, c] of Object.entries(CAMS)) {
86	    if (cams.length && !cams.includes(vn)) continue;
87	    await setCam(c); await frames(page, 6);
88	    const key = `${vn}-${cn}`;
89	    metrics.views[key] = await stats();
90	    if (!soft && info.timer && GPU_AT.some(([v, k]) => v === vn && k === cn)) {
91	      const g = await gpuMs(); metrics.gpuMs[key] = g;
92	      console.log(`  GPU ${key}: ${g ? `${g.med.toFixed(2)} ms (min ${g.min.toFixed(2)}, max ${g.max.toFixed(2)})` : 'không đo được'} · ${metrics.views[key].calls} lệnh vẽ · ${metrics.views[key].tris} tam giác`);
93	    }
94	    if (!noShots) { await frames(page, 2); await page.screenshot({ path: path.join(out, `${key}.png`) }); }
95	  }
96	  console.log(`${cn}: xong ${Object.keys(CAMS).length} góc`);
97	}
98	metrics.programsEnd = await page.evaluate(() => window.__app.renderer.info.programs.length);
99	metrics.heapMB = await page.evaluate(() => (performance.memory ? Math.round(performance.memory.usedJSHeapSize / 1048576) : null));
100	metrics.errors = errors;
101	await fs.writeFile(path.join(out, 'metrics.json'), JSON.stringify(metrics, null, 1));
102	console.log(`\nProgram cuối: ${metrics.programsEnd} · heap JS ${metrics.heapMB} MB · lỗi console: ${errors.length}`);
103	for (const e of errors) console.log('  LỖI console: ' + e);
104	console.log(`Đã ghi ${out}`);
105	await browser.close(); srv.close();
106	process.exit(errors.length ? 1 : 0);
107

