1	import * as THREE from 'three';
2	import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
3	import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
4	import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
5	import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
6	import { renderer, scene, camera } from './renderer';
7	import { pScale } from './shared';
8	import { clamp, smooth } from '../common/math';
9	import { CONFIG } from '../config';
10	
11	/* Bloom chỉ dùng khi trời tối: ban ngày vẫn vẽ thẳng như trước (không tốn thêm) */
12	export const composer = new EffectComposer(renderer);
13	composer.addPass(new RenderPass(scene, camera));
14	export const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0, 0.4, 0.98);
15	composer.addPass(bloomPass);
16	composer.addPass(new OutputPass());
17	
18	/* scale: tỉ lệ độ phân giải bloom so với màn hình (bậc chất lượng, D-018); 0 = tắt bloom, đêm vẽ thẳng như ban ngày */
19	export const bloomState = { scale: 1 };
20	export function renderFrame(night: number, dt: number) {
21	  const bloomK = smooth(clamp((night - 0.05) / 0.6, 0, 1));
22	  if (bloomK > 0.001 && bloomState.scale > 0) { bloomPass.strength = 0.6 * bloomK; composer.render(dt); }
23	  else renderer.render(scene, camera);
24	}
25	
26	/* Đổi pixelRatio (bậc chất lượng): cấp lại canvas + framebuffer composer một lần */
27	export function setPixelRatio(r: number) {
28	  if (Math.abs(renderer.getPixelRatio() - r) < 1e-3) return;
29	  renderer.setPixelRatio(r); onResize();
