quality.init(() => cam.mode === 'fly');   // bậc chất lượng ban đầu (theo thiết bị / lựa chọn đã lưu); không đổi bậc giữa chuyến bay camera
setupQualityUI();
setupCompactUI();
setupExplore(songHan.ctrl);

/* Móc kiểm thử: chỉ bật khi URL có ?test (dùng cho tests/*.mjs đo draw call và chạy Tour) */
/* Chỉ các lớp three mà tests/*.mjs dùng: đưa cả namespace THREE vào một object làm Rollup giữ lại mọi export của three (D-018) */
const TEST_THREE = { Vector3: THREE.Vector3, Quaternion: THREE.Quaternion, Matrix4: THREE.Matrix4, Euler: THREE.Euler, Box3: THREE.Box3, Raycaster: THREE.Raycaster };
/* ?test&perf: bật đo thời gian CPU từng bước trong vòng animate (tests/perf-check.mjs) */
const query = new URLSearchParams(location.search);
/* Cho test nhiều người (Task 5; sảnh thật là Task 6): mở phiên, vào phòng bằng tên, bay khi được cấp slot */
const multiTest = {
  url: () => exMulti.url(), get session() { return exMulti.session; }, remotes: exRemotes,
  fly(name: string): boolean {
    return exMulti.begin(() => {
      exMulti.onChange = () => { if (exMulti.session!.phase === 'flying' && !explore.active()) explore.start(); };
      exMulti.session!.join(name);
    });
  }
};
if (query.has('test')) {
  perf.on = query.has('perf');
  (window as unknown as { __app: unknown }).__app = { reflectState, renderer, scene, camera, controls, cam, shared, songHan, hr: hanTunnel, sunWheel, riverfront, weather, hrDrive, swRide, windFx, THREE: TEST_THREE, dayNight, lights: lightState, tours: TOURS, tour, narration, audio, perf, quality, ui: { ...ui, ui: compactState, openSheet, closeSheets, reveal }, explore, keys, multi: multiTest, exFlight: { exCreate, exStep, exInputFromKeys, exBuildGlider, exPlaceGlider, exChase, CONFIG_explore: CONFIG.explore }, boats: boatsTest, traffic: trafficTest, trees: treesTest, people: peopleTest, buildings: { state: bkState, attrs: () => bkAttrNames, shaped: bkShaped },
    stroll: { stroll, stValid, stGroundY, stMove, stCamPlace, CONFIG_stroll: CONFIG.stroll, avatars: stAvatars }, drive };
}

/* ============================ Vòng lặp ============================ */
const clock = new THREE.Clock();
const fpsEl = document.getElementById('fps'), callsEl = document.getElementById('calls'), showEl = document.getElementById('showState'), ftimeEl = document.getElementById('ftime');
let frames = 0, fpsT = 0, fpsLast = performance.now(), firstFrame = true;
function animate() {
  requestAnimationFrame(animate);
  const now0 = performance.now();
  perf.tick(now0);
  const dt = Math.min(clock.getDelta(), 0.05), time = clock.elapsedTime;
  let pt = perf.start();
  shared.uTime.value = time;
  shadowCenter.set(Math.round(controls.target.x / 8) * 8, 0, Math.round(controls.target.z / 8) * 8);
  stepNight(dt);
  applyNight(dayNight.night, time); pt = perf.lap('night', pt);
  updateWeather(dt, time, dayNight.night, camera);         // điều biến sau applyNight (D-009); camera: mưa quanh camera, tắt trong hầm
  water.material.uniforms.time.value += dt * 0.6 * windFx.waveSpeed;   // sóng trôi nhanh hơn theo gió (mặc định ×1)
  pt = perf.lap('weather', pt);
  updateShow(dt);
  updateEffects(dt, time); pt = perf.lap('effects', pt);
  updateTraffic(dt); updateDragonPeople(dt, time, camera); pt = perf.lap('traffic', pt);
  updateBoats(dt, time); pt = perf.lap('boats', pt);
  updateCamera(dt); explore.update(dt); stroll.update(dt); drive.update(dt); pt = perf.lap('camera', pt);
  for (let k = 0; k < bridges.length; k++) { bridges[k].update(dt, time, camera); pt = perf.lap(bridgeKeys[k], pt); }
  hanTunnel.holdBoats(songHan.boats.list);
  updateHrUI(camera);
  updateRiverfront(dt, time); pt = perf.lap('riverfront', pt);
  bkCull(camera);   // kit nhà: chỉ giữ nhà trong khung nhìn và trong tầm kitFar (kit.ts)
  audio.setSwingDistance(camera.position.distanceTo(songHan.center));
  audio.update(dayNight.night, show.fireOn, show.waterOn, camera.position.distanceTo(mouthW)); pt = perf.lap('audio', pt);
  stepLights();                                             // bộ đèn ngày / đêm / đủ (D-031): sau mọi chỗ ghi cường độ đèn, trước khi vẽ
  quality.update(now0);                                     // bậc chất lượng (tự hạ khi lag), bóng đổ, giới hạn pixelRatio khi mưa
  const pw = perf.start(); warmLightSets(); perf.lap('lightWarm', pw);   // hâm nền bộ đèn day / night (D-031 'bg'): sau quality.update (biết khung này có vẽ lại bóng), trước lượt vẽ thật; xong thì trả về ngay
  renderer.info.reset();
  renderFrame(dayNight.night, dt); stroll.afterRender(); drive.afterRender(); perf.lap('render', pt);   // gồm cả biên dịch shader lần đầu (đồng bộ trên luồng chính)
  frames++; const now = performance.now(); fpsT = (now - fpsLast) / 1000;
  if (fpsT >= 0.5) {
    fpsEl.textContent = String(Math.round(frames / fpsT)); fpsLast = now; callsEl.textContent = String(renderer.info.render.calls);
    const fs = perf.stats(); ftimeEl.textContent = `${fs.avg.toFixed(1)} · p95 ${fs.p95.toFixed(0)} · max ${fs.max.toFixed(0)}`;
    showEl.textContent = showLabel(); frames = 0; fpsT = 0;
  }
  if (firstFrame) { firstFrame = false; document.getElementById('loading').classList.add('done'); }
}
/* Người đi bộ đã là người thật (D-032) ⇒ không lưới nào trong cảnh dùng vật liệu hình khối peopleWalk, nhưng hình tạm của Đi dạo (blocky.ts) vẫn dùng.
   Thêm sẵn lưới đó vào cảnh (visible = false: không lệnh vẽ ở khung thường) để prewarm và hâm nền bộ đèn (D-031) biên dịch program của nó như mọi vật liệu khác;
   vào Đi dạo thì avatars.ts chuyển nó sang nhóm stroll-people. Không dùng rand / rng */
if (crowdUsable(crowdGet(), renderer.extensions.has('WEBGL_multi_draw'))) scene.add(stBlocky.build());
await prewarm();   // biên dịch sẵn shader + upload texture trong lúc còn màn hình chờ (D-018)
animate();

  shopLit: 0.8, shopGain: 0.9,                          // tỉ lệ cửa hàng sáng 0..1, cường độ (ước lượng)
  tubeLit: 0.55                                         // tỉ lệ cửa sổ sáng của nhà ống so với nhà thấp khác (cityNight.lowLit), 0..1 (ước lượng)
};

const perfBase = {
  hudSamples: 240,    // số khung giữ trong vòng mẫu để tính trung bình / p95 / max trên HUD (≈ 4 s ở 60 FPS)
  lightWarmMs: 3,     // ms — ngân sách mỗi khung cho phần đồng bộ (trên luồng chính) của biên dịch nền hai bộ đèn ngày / đêm (D-031) (ước lượng)
  lightWarmIgnoreMs: 50,   // ms — trong lúc hâm nền bộ đèn, khung dài hơn số này (biên dịch, đo 50–250 ms) bị bỏ khỏi trung bình của chế độ Tự động: không hạ bậc oan (ước lượng)
  lightWarmPrograms: 2,   // số program tối đa đang biên dịch dở khi biên dịch nền: dồn nhiều thì tiến trình GPU chặn khung (ước lượng, chọn theo đo)
  maxHitchMs: 150,    // ms — khung dài nhất cho phép khi đổi trạng thái (đêm, mặt cắt, bóng, bay tới công trình) (ước lượng, theo weather.perf.maxFrameMs)
  /* Bậc chất lượng, tốt → nhẹ. Chế độ Tự động đi lên/xuống theo thang này; chọn tay Cao/Trung bình/Thấp nhảy tới bậc `manual`.
     ratio: pixelRatio tối đa (không vượt devicePixelRatio); shadow: cạnh shadow map (px), 0 = tắt bóng; shadowEvery / reflectEvery: vẽ lại bóng / phản chiếu nước
     mỗi n khung (0 = tắt phản chiếu, mặt nước phản chiếu màu trời); bloom: tỉ lệ độ phân giải bloom ban đêm (0 = tắt); clouds: số tấm mây. Mọi số (ước lượng), chỉnh theo đo trên GPU thật */
  steps: [
    { tier: 'high', ratio: 2, shadow: 2048, shadowEvery: 1, reflectEvery: 1, bloom: 1, clouds: 26 },      // = cảnh gốc (bảng draw call chuẩn đo ở bậc này)
    { tier: 'high', ratio: 1.5, shadow: 2048, shadowEvery: 1, reflectEvery: 1, bloom: 1, clouds: 26 },
    { tier: 'medium', ratio: 1.5, shadow: 1024, shadowEvery: 2, reflectEvery: 2, bloom: 0.5, clouds: 26 },
    { tier: 'medium', ratio: 1.25, shadow: 1024, shadowEvery: 2, reflectEvery: 2, bloom: 0.5, clouds: 26 },
    { tier: 'medium', ratio: 1, shadow: 1024, shadowEvery: 2, reflectEvery: 3, bloom: 0.5, clouds: 18 },
    { tier: 'low', ratio: 1, shadow: 0, shadowEvery: 1, reflectEvery: 0, bloom: 0, clouds: 12 },
    { tier: 'low', ratio: 0.75, shadow: 0, shadowEvery: 1, reflectEvery: 0, bloom: 0, clouds: 12 }
  ],
  manual: { high: 0, medium: 2, low: 5 } as Record<'high' | 'medium' | 'low', number>,   // bậc ứng với lựa chọn tay
  adapt: {
    window: 2,          // s — cửa sổ đo thời gian khung trung bình
    downMs: 22,         // ms — trung bình cửa sổ trên mức này (≈ dưới 45 FPS) thì hạ một bậc
    upMs: 12,           // ms — trung bình dưới mức này (≈ trên 80 FPS) liên tục `upHold` giây thì nâng một bậc
    upHold: 10,         // s
    cooldown: 3,        // s — tối thiểu giữa hai lần đổi bậc (đổi pixelRatio phải cấp lại framebuffer)
    ignoreMs: 400       // ms — bỏ khung dài hơn (đổi tab, biên dịch một lần) khỏi trung bình: không hạ chất lượng vì một lần giật
  },
  rainMaxRatio: 1.5,    // pixelRatio tối đa khi mưa đang hiện (thay cho weather.perf.rainMaxPixelRatio, áp qua bộ quản lý chất lượng)
  start: { phone: 5, weak: 2 }   // bậc khởi đầu ở chế độ Tự động: điện thoại / máy tính yếu (≤ 4 GB RAM hoặc ≤ 4 luồng); còn lại bậc 0
};

/* ------------------------- Giao diện gọn (điện thoại) -------------------------
   Chế độ gọn bật khi cửa sổ khớp compactQuery: bảng điều khiển thu thành hai tờ (Cài đặt / Góc nhìn) */
const uiBase = {
  compactQuery: '(max-width: 760px), (max-height: 500px)',   // media query bật chế độ gọn: điện thoại dọc (≤ 760 px rộng) hoặc ngang (≤ 500 px cao)
  resizeDebounceMs: 120,   // ms — chờ sau khi đổi cỡ cửa sổ / xoay máy rồi mới tính lại bố cục (ước lượng)
  donate: {
    url: 'https://me.momo.vn/bbk9x'   // URL nhận tiền MoMo; dùng alias riêng, không dùng số điện thoại vì URL nằm trong bundle công khai
  }
};

/* ------------------------- Tự khám phá bằng dù lượn -------------------------
   Chế độ bay tự do (W/A/S/D), mô hình bay ở explore/flight.ts. Mọi số đều (ước lượng) */
