10	/* =====================================================================
11	   CHẤT LƯỢNG HÌNH (D-018) — thang bậc ở CONFIG.perf.steps (0 = cảnh gốc). Chế độ:
12	   - 'auto': đo thời gian khung trung bình; chậm (> downMs) thì hạ một bậc, nhanh (< upMs) đủ lâu thì nâng một bậc.
13	   - 'high' | 'medium' | 'low': đứng yên ở bậc tương ứng (CONFIG.perf.manual).
14	   Khi chạy chỉ đổi những thứ không làm biên dịch lại shader: pixelRatio, cỡ shadow map, chu kỳ vẽ bóng / phản chiếu, độ phân giải bloom, số tấm mây.
15	   ?test: luôn bậc 0 và không tự đổi (bảng draw call chuẩn), trừ khi test gọi set().
16	   ===================================================================== */
17	export type QualityMode = 'auto' | 'high' | 'medium' | 'low';
18	type Step = (typeof CONFIG.perf.steps)[number];
19	const P = CONFIG.perf, STORE = 'dn3d-quality';
20	
21	const loadMode = (): QualityMode => {
22	  if (device.test) return 'high';
23	  try { const v = localStorage.getItem(STORE); if (v === 'auto' || v === 'high' || v === 'medium' || v === 'low') return v; } catch { /* trình duyệt chặn lưu trữ */ }
24	  return 'auto';
25	};
26	const startStep = (mode: QualityMode) => mode === 'auto' ? (device.phone ? P.start.phone : device.weak ? P.start.weak : 0) : P.manual[mode];
27	
28	let busy: () => boolean = () => false;
29	let winSum = 0, winN = 0, winT = 0, fastT = 0, lastChange = 0, last = 0;
30	let appliedStep: Step | null = null, appliedRatio = 0;
31	
32	export const quality = {
33	  mode: loadMode(),
34	  step: 0,
35	  changes: 0,                // số lần đã đổi bậc (test)
36	  adapt: { ...P.adapt },     // bản sao chỉnh được (test rút ngắn cửa sổ / thời gian giữ)
37	  simulateMs: 0,             // > 0: thay thời gian khung đo được bằng số này (test giả lập máy chậm / nhanh; bật cả khi ?test)
38	  /* Gọi một lần lúc khởi động, TRƯỚC prewarm: điện thoại ở bậc Thấp thì tắt castShadow từ đầu (đỡ lấy mẫu bóng; xem lights.ts) */
39	  init(isBusy?: () => boolean) {
40	    if (isBusy) busy = isBusy;
41	    this.step = startStep(this.mode);
42	    if (device.phone && P.steps[this.step].shadow === 0) sun.castShadow = false;
43	    this.apply(true);
44	  },
45	  /* Đổi chế độ (ô chọn / test). Lưu lựa chọn (trừ ?test) */
46	  set(mode: QualityMode) {
47	    this.mode = mode;
48	    if (!device.test) try { localStorage.setItem(STORE, mode); } catch { /* bỏ qua */ }
49	    this.step = startStep(mode); fastT = 0; winSum = winN = 0; winT = 0;
50	    this.apply(true);
51	  },
52	  current(): Step { return P.steps[this.step]; },
53	  /* Áp bậc hiện tại (pixelRatio có tính giới hạn khi mưa) */
54	  apply(force = false) {
55	    const s = P.steps[this.step], rainCap = rainShowing() ? P.rainMaxRatio : Infinity;
56	    const ratio = Math.min(window.devicePixelRatio || 1, s.ratio, rainCap);
57	    if (!force && s === appliedStep && ratio === appliedRatio) return;   // so sánh trực tiếp: hàm chạy mỗi khung, không tạo chuỗi
58	    appliedStep = s; appliedRatio = ratio; this.changes++;
59	    setShadowQuality(s.shadow, s.shadowEvery);
60	    reflectState.every = s.reflectEvery;
61	    clouds.count = Math.min(s.clouds, clouds.instanceMatrix.count);
62	    const bloomChanged = bloomState.scale !== s.bloom;
63	    bloomState.scale = s.bloom;
64	    setPixelRatio(ratio);
65	    if (bloomChanged) onResize();   // cỡ bloom theo bloomState.scale
66	  },
67	  /* Mỗi khung, trước khi vẽ. now = performance.now() */
68	  update(now: number) {
69	    const dtMs = last ? now - last : 0; last = now;
70	    this.apply();   // mưa bật/tắt đổi giới hạn pixelRatio
71	    stepShadows();
72	    const A = this.adapt, ms = this.simulateMs || dtMs;
73	    if (this.mode !== 'auto' || (device.test && !this.simulateMs) || !ms || ms > (lightsWarming() ? Math.min(A.ignoreMs, P.lightWarmIgnoreMs) : A.ignoreMs) || document.hidden) return;
74	    winSum += ms; winN++; winT += ms / 1000;
75	    if (winT < A.window) return;
76	    const avg = winSum / winN, sinceChange = (now - lastChange) / 1000;
77	    winSum = winN = 0; winT = 0;
78	    fastT = avg < A.upMs ? fastT + A.window : 0;
79	    if (busy() || sinceChange < A.cooldown) return;
80	    let next = this.step;
81	    if (avg > A.downMs && this.step < P.steps.length - 1) next = this.step + 1;
82	    else if (fastT >= A.upHold && this.step > 0) { next = this.step - 1; fastT = 0; }
83	    if (next === this.step) return;
84	    this.step = next; lastChange = now; this.apply();
85	  }
86	};
