39	export function onResize() {
40	  camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix();
41	  renderer.setSize(window.innerWidth, window.innerHeight);
42	  composer.setPixelRatio(renderer.getPixelRatio()); composer.setSize(window.innerWidth, window.innerHeight);
43	  if (bloomState.scale > 0 && bloomState.scale < 1) { const pr = renderer.getPixelRatio() * bloomState.scale; bloomPass.setSize(window.innerWidth * pr, window.innerHeight * pr); }
