// Dò phản hồi "nước sông ban đêm, chất lượng Cao hơi giật" (docs/ai/QA_LOG.md, M4). GPU THẬT, vòng animate thật của trang
// (composer + bloom, bộ đèn theo ?lightsets, pixelRatio theo màn hình), khác ven-song-shots.mjs vốn chỉ đo renderer.render ở pixelRatio 1.
// Không chấm đạt / lỗi: chỉ in số và ghi tests/screens/ven-song/<nhãn>/probe.json (+ ảnh cắt vùng nước khi --flicker).
//
//   node tests/ven-song-night-probe.mjs --label=dem-B [--dist=<thư mục>] [--dpr=2] [--w=1440] [--h=900] [--query=lightsets=sync]
//        [--cams=doc-song,sat-nuoc,tren-cao] [--parts] [--flicker] [--warm=90]
//   --parts:   tách chi phí trên cùng một trang: pixelRatio 2 / 1,5 / 1, tắt bloom, tắt vệt đèn (vá shader lúc chạy), tắt gương
//   --flicker: đo nhấp nháy vùng nước giữa các khung liên tiếp (độ chói đổi mỗi 1/60 s), lưu 3 ảnh cắt liên tiếp
//   --warm=N:  ghi khung dài trong N giây đầu ở ban đêm (hâm nền bộ đèn, cần --query=lightsets=bg)
import { fileURLToPath } from 'node:url';
import fs from 'node:fs/promises';
import path from 'node:path';
import { chromium } from 'playwright';
import { serveDir } from './lib.mjs';

const arg = (k, d) => process.argv.find((a) => a.startsWith(`--${k}=`))?.slice(k.length + 3) ?? d;
const has = (k) => process.argv.includes(`--${k}`);
const label = arg('label', 'probe'), W = +arg('w', 1440), H = +arg('h', 900), DPR = +arg('dpr', 2), warmSecs = +arg('warm', 0);
const camList = arg('cams', 'doc-song,sat-nuoc,tren-cao').split(',').filter(Boolean);
const CAMS = {
  'tren-cao': { pos: [-430, 330, 560], target: [0, 12, 0] },
  'doc-song': { pos: [0, 45, -640], target: [0, 80, -1150] },
  'sat-nuoc': { pos: [-120, 5, -260], target: [60, 2, -700] },
  'bo-ke': { pos: [-266, 4.6, -1165], target: [-40, 9, -1075] },
  'du-luon': { pos: [40, 140, 520], target: [-60, 0, -500] }
};
const out = fileURLToPath(new URL(`./screens/ven-song/${label}/`, import.meta.url));
await fs.mkdir(out, { recursive: true });
const srv = await serveDir(arg('dist', '') ? path.resolve(arg('dist', '')) : fileURLToPath(new URL('../dist/', import.meta.url)));
const args = ['--ignore-gpu-blocklist', '--enable-gpu'];
if (process.platform === 'win32') args.unshift('--use-angle=d3d11');
const browser = await chromium.launch({ headless: true, args });
const page = await browser.newPage({ viewport: { width: W, height: H }, deviceScaleFactor: DPR });
const errors = []; page.setDefaultTimeout(240000);
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::/.test(m.text())) errors.push(m.text()); });
await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
const q = arg('query', '');
await page.goto(srv.url + '?test&perf' + (q ? '&' + q : ''), { waitUntil: 'load', timeout: 180000 });
await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });

const state = () => page.evaluate(() => {
  const A = window.__app, R = A.renderer, gl = R.getContext(), d = gl.getExtension('WEBGL_debug_renderer_info');
  return { gpu: d ? gl.getParameter(d.UNMASKED_RENDERER_WEBGL) : '?', ratio: R.getPixelRatio(), buf: [gl.drawingBufferWidth, gl.drawingBufferHeight], dpr: devicePixelRatio,
    set: A.lights?.set, mode: A.lights?.mode, ready: A.lights ? { ...A.lights.ready } : null, programs: R.info.programs.length, step: A.quality.step };
});
const setCam = (c) => page.evaluate((c) => {
  const A = window.__app; A.cam.mode = 'orbit'; A.controls.enabled = true; A.controls.maxPolarAngle = Math.PI * 0.97;
  A.camera.position.set(...c.pos); A.controls.target.set(...c.target); A.controls.update();
}, c);
const setNight = (n) => page.evaluate((n) => { const d = window.__app.dayNight; d.target = d.night = n; }, n);
const raf = (n) => page.evaluate((n) => new Promise((ok) => { let i = 0; const f = () => (++i >= n ? ok() : requestAnimationFrame(f)); requestAnimationFrame(f); }), n);

/* Đo vòng animate thật trong n khung: khoảng cách rAF (ms) và thời gian GPU (truy vấn TIME_ELAPSED bao 12 khung một, gồm bóng + gương + bloom) */
const measure = (n = 180) => page.evaluate(async (n) => {
  const A = window.__app, gl = A.renderer.getContext(), ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
  const dts = [], qs = []; let last = 0, cur = null, k = 0;
  await new Promise((ok) => {
    const f = (t) => {
      if (last) dts.push(t - last); last = t;
      if (ext) { if (cur && k % 12 === 0) { gl.endQuery(ext.TIME_ELAPSED_EXT); qs.push(cur); cur = null; } if (!cur && dts.length < n) { cur = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, cur); k = 0; } k++; }
      if (dts.length >= n) { if (cur) { gl.endQuery(ext.TIME_ELAPSED_EXT); gl.deleteQuery(cur); cur = null; } ok(); } else requestAnimationFrame(f);
    };
    requestAnimationFrame(f);
  });
  const g = [];
  for (const qq of qs) {
    for (let i = 0; i < 400 && !gl.getQueryParameter(qq, gl.QUERY_RESULT_AVAILABLE); i++) await new Promise((ok) => setTimeout(ok, 5));
    if (!gl.getParameter(ext.GPU_DISJOINT_EXT)) g.push(gl.getQueryParameter(qq, gl.QUERY_RESULT) / 1e6 / 12);
    gl.deleteQuery(qq);
  }
  dts.sort((a, b) => a - b); g.sort((a, b) => a - b);
  const pc = (a, p) => a.length ? a[Math.min(a.length - 1, Math.floor(a.length * p))] : -1, cpu = A.perf.stats ? A.perf.stats() : null;
  return { gpu: pc(g, 0.5), gpuMax: pc(g, 1), dt: dts.reduce((s, x) => s + x, 0) / dts.length, p50: pc(dts, 0.5), p95: pc(dts, 0.95), max: pc(dts, 1), over20: dts.filter((x) => x > 20).length, n: dts.length,
    cpu: cpu ? cpu.avg : -1, calls: A.renderer.info.render.calls, set: A.lights?.set };
}, n);
const fmt = (m) => `GPU ${m.gpu.toFixed(2)} ms (max ${m.gpuMax.toFixed(1)}) · khung ${m.dt.toFixed(1)} ms, p95 ${m.p95.toFixed(1)}, max ${m.max.toFixed(0)}, ${m.over20}/${m.n} khung > 20 ms · CPU ${m.cpu.toFixed(1)} ms · ${m.calls} lệnh vẽ · bộ đèn ${m.set}`;

const res = { label, when: new Date().toISOString(), query: q, open: await state(), views: {}, parts: {}, flicker: {}, warm: null, errors };
console.log(`${label}: ${res.open.gpu} · ${W}x${H} @${res.open.dpr} → pixelRatio ${res.open.ratio}, bộ đệm ${res.open.buf.join('x')} · ${res.open.programs} program · lightsets ${res.open.mode}`);

/* (2) Khung dài trong N giây đầu ở ban đêm: ghi mọi khung > 33 ms kèm thời điểm và lúc bộ đèn sẵn sàng */
if (warmSecs) {
  await setNight(1); await setCam(CAMS['doc-song']);
  res.warm = await page.evaluate((secs) => new Promise((ok) => {
    const A = window.__app, t0 = performance.now(), long = [], ev = []; let last = 0, n = 0, sum = 0, rd = false, rn = false, set = A.lights.set;
    const f = (t) => {
      const el = (performance.now() - t0) / 1000;
      if (last) { const d = t - last; n++; sum += d; if (d > 33) long.push([+el.toFixed(1), Math.round(d)]); } last = t;
      if (!rd && A.lights.ready.day) { rd = true; ev.push(['day sẵn sàng', +el.toFixed(1)]); }
      if (!rn && A.lights.ready.night) { rn = true; ev.push(['night sẵn sàng', +el.toFixed(1)]); }
      if (A.lights.set !== set) { set = A.lights.set; ev.push(['chuyển sang ' + set, +el.toFixed(1)]); }
      if (el >= secs) ok({ frames: n, avg: sum / n, long, ev, programs: A.renderer.info.programs.length }); else requestAnimationFrame(f);
    };
    requestAnimationFrame(f);
  }), warmSecs);
  const w = res.warm;
  console.log(`  ${warmSecs} s đầu ở đêm: ${w.frames} khung, trung bình ${w.avg.toFixed(1)} ms, ${w.long.length} khung > 33 ms, ${w.long.filter((x) => x[1] > 100).length} khung > 100 ms, dài nhất ${Math.max(0, ...w.long.map((x) => x[1]))} ms · ${w.ev.map((e) => `${e[0]} ${e[1]} s`).join(', ')} · ${w.programs} program`);
}

await setNight(1); await raf(30);
for (const vn of camList) {
  await setCam(CAMS[vn]); await raf(20);
  res.views[vn] = await measure();
  console.log(`  ${vn} đêm: ${fmt(res.views[vn])}`);
}

/* (1) Tách chi phí ở góc đầu danh sách: sửa bậc 0 của CONFIG.perf.steps rồi quality.apply(true) (đổi pixelRatio / bloom / gương không biên dịch lại shader) */
if (has('parts')) {
  const vn = camList[0]; await setCam(CAMS[vn]);
  const tweak = (o) => page.evaluate((o) => { const A = window.__app, s = A.quality.current(); Object.assign(s, o); A.quality.apply(true); return { ratio: A.renderer.getPixelRatio(), s: { ...s } }; }, o);
  const base = await page.evaluate(() => ({ ...window.__app.quality.current() }));
  const run = async (name, o) => { const r = await tweak({ ...base, ...o }); await raf(20); const m = await measure(120); res.parts[name] = { ...m, ratio: r.ratio }; console.log(`  [${vn}] ${name} (pixelRatio ${r.ratio}): ${fmt(m)}`); };
  await run('gốc', {});
  await run('tắt bloom', { bloom: 0 });
  await run('tắt gương', { reflectEvery: 0 });
  await run('pixelRatio 1,5', { ratio: 1.5 });
  await run('pixelRatio 1', { ratio: 1 });
  await run('pixelRatio 1 + tắt bloom', { ratio: 1, bloom: 0 });
  await tweak(base);
  const patched = await page.evaluate(() => {   // tắt vòng lấy mẫu vệt đèn: vá chuỗi điều kiện trong fragment shader nước rồi biên dịch lại (chỉ trong trang đo)
    let ok = false;
    window.__app.scene.traverse((o) => { const m = o.material; if (m?.uniforms?.mirrorSampler && m.fragmentShader.includes('uNight > 0.85')) { m.fragmentShader = m.fragmentShader.replace('uNight > 0.85', 'uNight > 8.5'); m.needsUpdate = true; ok = true; } });
    return ok;
  });
  if (patched) { await raf(40); await run('tắt vệt đèn', {}); } else console.log('  không vá được shader nước (không thấy chuỗi "uNight > 0.85")');
}

/* (3) Nhấp nháy: 24 khung liên tiếp, cắt vùng nước nửa dưới giữa màn hình; đo |Δ độ chói| giữa hai khung kề nhau */
if (has('flicker')) {
  if (has('parts')) await page.reload({ waitUntil: 'load' }).then(() => page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done')));
  await setNight(1); await raf(30);
  for (const vn of camList) {
    await setCam(CAMS[vn]); await raf(30);
    const f = await page.evaluate(() => new Promise((ok) => {
      const A = window.__app, src = A.renderer.domElement, cw = Math.round(src.width * 0.5), ch = Math.round(src.height * 0.3), sx = Math.round(src.width * 0.25), sy = Math.round(src.height * 0.62);
      const cv = document.createElement('canvas'); cv.width = cw; cv.height = ch; const cx = cv.getContext('2d', { willReadFrequently: true });
      const lum = [], pngs = [], dts = []; let last = 0;
