      const q = open.find((o) => o.id === `${m[1]}.${m[2] === 'W' ? 'E' : 'S'}`);
      if (q) medians.push(m[2] === 'W' ? { x0: p.x1, x1: q.x0, z0: p.z0, z1: p.z1 } : { x0: p.x0, x1: p.x1, z0: p.z1, z1: q.z0 });
