    mesh.name = 'stroll-blocky';
    for (let i = 0; i < N; i++) { mesh.setColorAt(i, col.set(M.colors[i % M.colors.length])); mesh.setMatrixAt(i, _zero); }   // setColorAt bắt buộc (USE_INSTANCING_COLOR)
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.layers.set(1); mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
    shown.fill(0); cur.fill(-1); mesh.visible = false;
    return mesh;
  },

  /* Instance i: hiện tại (x, y, z) hướng yaw với dáng pose (speed cho nhịp bước), hoặc ẩn (st = null) */
  place(i: number, st: { x: number; y: number; z: number; yaw: number; pose: number } | null, speed: number): void {
    if (!mesh || !aVar) return;
    if (!st) {
      if (!shown[i]) return;
      shown[i] = 0; mesh.setMatrixAt(i, _zero); mesh.instanceMatrix.needsUpdate = true;
      return;
    }
    shown[i] = 1;
    mesh.setMatrixAt(i, _m.compose(_p.set(st.x, st.y, st.z), _q.setFromAxisAngle(_up, st.yaw), _one));   // hình hướng +X: quay yaw quanh Y ra (cos yaw, 0, −sin yaw)
    mesh.instanceMatrix.needsUpdate = true;
    stAvatarVar(st.pose, speed, _var);
    const c = i * 3;
    if (_var.amp === cur[c] && _var.cadence === cur[c + 1] && _var.flags === cur[c + 2]) return;
    const a = aVar.array as Float32Array, o = i * 4, now = shared.uTime.value;
    const ph = now * a[o + 3] + a[o];   // giữ pha liền khi đổi nhịp: φ(now) không nhảy
    a[o] = (((ph - now * _var.cadence) % TAU) + TAU) % TAU; a[o + 1] = _var.amp; a[o + 2] = _var.flags; a[o + 3] = _var.cadence;
    cur[c] = _var.amp; cur[c + 1] = _var.cadence; cur[c + 2] = _var.flags;
    aVar.needsUpdate = true;
  },

  /* Ẩn cả mesh khi không instance nào hiện (không tốn lệnh vẽ) */
  refresh(): void {
    if (!mesh) return;
    let any = false;
    for (let i = 0; i < N; i++) if (shown[i]) { any = true; break; }
    mesh.visible = any;
  }
};
function stDrop(i: number): void {
  const s = slots[i];
  if (!s.rig) return;
  s.rig.dispose(); s.rig = null; s.model = -1;
}

/* Đặt slot i theo s.st: nhân vật thật nếu mô hình đã có, không thì hình khối. speed (m/s) chọn đoạn / nhịp bước, dt (s) cho mixer */
function stPlace(i: number, speed: number, dt: number): void {
  const s = slots[i];
  if (!group) return;
  if (!s.live) { stBlocky.place(i, null, 0); if (s.rig) s.rig.root.visible = false; return; }
  const model = stModelFor(i, s.who === 1);
  if (s.rig && s.model !== model) stDrop(i);
  if (!s.rig) {
    const src = stNeed(model);
    if (src) { s.rig = new StRig(src); s.model = model; group.add(s.rig.root); }
  }
  const t = s.st;
  if (!s.rig) { stBlocky.place(i, t, speed); return; }
  stBlocky.place(i, null, 0);
  const r = s.rig.root;
  r.visible = true;
  r.position.set(t.x, t.y, t.z); r.rotation.set(0, t.yaw, 0);   // mô hình hướng +X như hình khối: yaw quanh Y
  s.rig.pose(t.pose, speed, dt);
}

function stHide(i: number): void {
  const s = slots[i];
  s.track.reset(); s.live = false;
  stDrop(i);
  stPlace(i, 0, 0);
}

function stRefreshVisible(): void {
  if (!group) return;
  let any = false;
  for (const s of slots) if (s.live) { any = true; break; }
  group.visible = any;
  stBlocky.refresh();
}

/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);

export const stAvatars = {
  get mesh(): THREE.Group | null { return group; },
  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)

