page.on('console', (m) => { if (/warn|error/.test(m.type())) console.log('[' + m.type() + ']', m.text().slice(0, 200)); });
if (!process.argv.includes('--noblock')) await page.route('**/people/*.glb', (q) => q.abort());
await page.goto(srv.url + '?explore=stroll&test', { waitUntil: 'load' });
await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
