  await page.waitForTimeout(1500);
  console.log(JSON.stringify(await page.evaluate(() => { const a = window.__app, V = a.stroll.avatars, g = V.mesh, b = a.scene.getObjectByName('stroll-blocky');
    const m = new a.THREE.Matrix4(); const sc = []; if (b) for (let i = 0; i < b.count; i++) { b.getMatrixAt(i, m); sc.push(+m.elements[0].toFixed(2)); }
    return { self: V.self, dbg: V.self >= 0 ? V.debug(V.self) : null, gVis: g?.visible, bVis: b?.visible, bParent: b?.parent?.name || b?.parent?.type, count: b?.count, sc, act: a.stroll.stroll.active() }; })));
}
await browser.close(); srv.close();
JSEOF
