  local code=$? t1=$(date +%s)
  printf '%s\t%s\t%s\t%d phút\texit %d\n' "$name" "$s0" "$(date '+%H:%M')" $(( (t1 - t0) / 60 )) "$code" >> "$SUM"
  if [ "$code" -eq 124 ]; then   # hết giờ: dọn Chromium của Playwright và node test còn sót (không đụng Chrome của người dùng)
    powershell -NoProfile -Command "Get-CimInstance Win32_Process | Where-Object { (\$_.ExecutablePath -like '*ms-playwright*') -or (\$_.CommandLine -match 'check\.mjs|drawcalls\.mjs|gpu-time\.mjs|wrangler') } | ForEach-Object { Stop-Process -Id \$_.ProcessId -Force -ErrorAction SilentlyContinue }" >/dev/null 2>&1
  fi
}
for spec in "$@"; do
  case "$spec" in
    perf) run perf 120 node tests/perf-check.mjs --strict ;;
    drawcalls) run drawcalls 150 node tests/drawcalls.mjs ;;
    gpu) run gpu 60 node tests/gpu-time.mjs ;;
    drive) run drive 240 node tests/drive-check.mjs ;;
    multi) run multi 180 node tests/multi-check.mjs ;;
    tunnel) run tunnel 180 node tests/tunnel-check.mjs ;;
    *) run "$spec" 150 node "tests/$spec-check.mjs" ;;
  esac
done
echo "# xong $(date '+%Y-%m-%d %H:%M')" >> "$SUM"
